const results = [];
for (const item of $input.all()) {
  const url = item.json.source_url;
  const manualDescription = item.json.manual_description || '';
  let sourceType = '';
  if (url.includes('youtube.com') || url.includes('youtu.be')) sourceType = 'youtube';
  else if (url.includes('instagram.com/reel') || url.includes('instagram.com/p/')) sourceType = 'instagram';

  if (!sourceType) {
    results.push({ json: { source_url: url, source_type: 'unknown', video_id: '', title: 'ERROR: Unsupported URL', transcript: '', duration_seconds: 0, aspect_ratio: '16:9', video_stream_urls: [], manual_description: manualDescription } });
    continue;
  }

  if (sourceType === 'youtube') {
    let vid = '';
    if (url.includes('v=')) vid = url.split('v=')[1].split('&')[0];
    else if (url.includes('youtu.be/')) vid = url.split('youtu.be/')[1].split('?')[0];
    else if (url.includes('/shorts/')) vid = url.split('/shorts/')[1].split('?')[0];
    if (!vid) { results.push({ json: { source_url: url, source_type: 'youtube', video_id: '', title: 'ERROR: Invalid YouTube URL', transcript: '', duration_seconds: 0, aspect_ratio: '16:9', video_stream_urls: [] } }); continue; }

    let title = '';
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://www.youtube.com/oembed?format=json&url=https://www.youtube.com/watch?v=' + vid });
      title = (typeof r === 'string' ? JSON.parse(r) : r).title || '';
    } catch (e) { title = 'Untitled Video'; }

    let transcript = ''; let duration_seconds = 0; let videoStreamUrls = [];
    const clients = [
      { clientName: 'ANDROID', clientVersion: '19.09.37' },
      { clientName: 'IOS', clientVersion: '19.09.3' },
      { clientName: 'WEB', clientVersion: '2.20240313.00.00' }
    ];
    for (const client of clients) {
      try {
        const playerResp = await this.helpers.httpRequest({
          method: 'POST', url: 'https://www.youtube.com/youtubei/v1/player?prettyPrint=false',
          headers: { 'Content-Type': 'application/json', 'User-Agent': 'Mozilla/5.0' },
          body: JSON.stringify({ videoId: vid, context: { client: { ...client, hl: 'en' } } })
        });
        const pd = typeof playerResp === 'string' ? JSON.parse(playerResp) : playerResp;
        if (!duration_seconds) duration_seconds = parseInt(pd?.videoDetails?.lengthSeconds || '0', 10);
        const formats = [...(pd?.streamingData?.formats || []), ...(pd?.streamingData?.adaptiveFormats || [])];
        for (const f of formats) {
          if (f.url && f.mimeType && f.mimeType.includes('video/mp4')) {
            videoStreamUrls.push({ url: f.url, itag: f.itag, quality: f.qualityLabel || f.quality || '', width: f.width || 0 });
          }
        }
        if (!transcript) {
          const tracks = pd?.captions?.playerCaptionsTracklistRenderer?.captionTracks;
          if (tracks && tracks.length > 0) {
            const t = tracks.find(t => t.languageCode === 'en') || tracks[0];
            const caps = await this.helpers.httpRequest({ method: 'GET', url: t.baseUrl + '&fmt=json3' });
            const cd = typeof caps === 'string' ? JSON.parse(caps) : caps;
            transcript = (cd.events || []).filter(e => e.segs).map(e => e.segs.map(s => s.utf8).join('')).join(' ').replace(/\s+/g, ' ').trim();
          }
          if (!transcript) { const desc = pd?.videoDetails?.shortDescription; if (desc && desc.length > 10) transcript = desc; }
        }
        if (videoStreamUrls.length > 0) break;
      } catch (e) {}
    }
    if (!transcript) transcript = 'No transcript available.';
    videoStreamUrls.sort((a, b) => (a.width || 9999) - (b.width || 9999));
    results.push({ json: { source_url: url, source_type: 'youtube', video_id: vid, title, transcript, duration_seconds, aspect_ratio: url.includes('/shorts/') ? '9:16' : '16:9', video_stream_urls: videoStreamUrls, manual_description: manualDescription } });
  }

  if (sourceType === 'instagram') {
    const reelMatch = url.match(/instagram\.com\/(?:reel|reels|p)\/([A-Za-z0-9_-]+)/);
    const shortcode = reelMatch ? reelMatch[1] : '';
    if (!shortcode) { results.push({ json: { source_url: url, source_type: 'instagram', video_id: '', title: 'ERROR: Invalid Instagram URL', transcript: '', duration_seconds: 0, aspect_ratio: '9:16', video_stream_urls: [] } }); continue; }
    let title = ''; let igThumbUrl = ''; let igCaption = '';
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://www.instagram.com/api/v1/oembed/?url=' + encodeURIComponent(url) + '&format=json', headers: { 'User-Agent': 'Mozilla/5.0' } });
      const d = typeof r === 'string' ? JSON.parse(r) : r;
      title = d.title || (d.author_name ? 'Instagram Reel by ' + d.author_name : '');
      igThumbUrl = d.thumbnail_url || '';
      igCaption = d.title || '';
    } catch (e) {}
    if (!igThumbUrl || !title) {
      try {
        const page = await this.helpers.httpRequest({ method: 'GET', url: url, headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/121.0.0.0 Safari/537.36', 'Accept': 'text/html', 'Accept-Language': 'en-US,en;q=0.9' }, timeout: 15000 });
        const pageStr = typeof page === 'string' ? page : JSON.stringify(page);
        if (!igThumbUrl) {
          const cdnMatch = pageStr.match(/content="(https:\/\/scontent[^"]+cdninstagram[^"]+)"/);
          if (cdnMatch) igThumbUrl = cdnMatch[1].replace(/&amp;/g, '&');
        }
        if (!title) {
          const titleMatch = pageStr.match(/content="([^"]{5,200})\s*(?:\&#064;|@)\s*[^"]*\s*(?:\&#x2022;|\u2022)\s*Instagram/i);
          if (titleMatch) title = titleMatch[0].replace(/content="/, '').replace(/"/g, '').replace(/&#064;/g, '@').replace(/&#x2022;/g, '-');
          if (!title) {
            const ogTitle = pageStr.match(/property="og:title"\s+content="([^"]+)"/);
            if (ogTitle) title = ogTitle[1].replace(/&amp;/g, '&').replace(/&#39;/g, "'");
          }
        }
        if (!igCaption) {
          const descMatch = pageStr.match(/property="og:description"\s+content="([^"]+)"/);
          if (descMatch) igCaption = descMatch[1].replace(/&amp;/g, '&').replace(/&#39;/g, "'");
        }
      } catch (e2) {}
    }
    if (!title) title = 'Instagram Reel ' + shortcode;
    let igThumbBase64 = '';
    if (igThumbUrl) {
      try {
        const tr = await this.helpers.httpRequest({ method: 'GET', url: igThumbUrl, encoding: 'arraybuffer', returnFullResponse: true, timeout: 10000, headers: { 'User-Agent': 'Mozilla/5.0' } });
        const buf = Buffer.from(tr.body);
        if (buf.length > 3000) igThumbBase64 = buf.toString('base64');
      } catch (e) {}
    }
    results.push({ json: { source_url: url, source_type: 'instagram', video_id: shortcode, title, transcript: igCaption || title, duration_seconds: 0, aspect_ratio: '9:16', video_stream_urls: [], ig_thumbnail_base64: igThumbBase64, manual_description: manualDescription } });
  }
}
return results;

// SINGLE Gemini call per video: analyze + generate 4 ready-to-paste prompts
const GEMINI_KEY = 'AIzaSyDGs6effDaTvVzlnxKitiqE366r20lAfQQ';
const allResults = [];

for (const inputItem of $input.all()) {
const item = inputItem.json;

try {
  let fileUri = '';
  let usedVideo = false;
  let usedThumbnails = false;
  let thumbnailBase64List = [];
  let debugInfo = [];

  // STEP 1: Try uploading actual video to Gemini
  const streamUrls = item.video_stream_urls || [];
  for (let i = 0; i < Math.min(streamUrls.length, 5); i++) {
    if (usedVideo) break;
    try {
      debugInfo.push('Try itag=' + streamUrls[i].itag);
      const videoResp = await this.helpers.httpRequest({
        method: 'GET', url: streamUrls[i].url, encoding: 'arraybuffer', returnFullResponse: true, timeout: 90000,
        headers: { 'User-Agent': 'Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36', 'Accept': '*/*', 'Accept-Encoding': 'identity', 'Range': 'bytes=0-' }
      });
      const buf = Buffer.from(videoResp.body);
      const sizeMB = buf.length / (1024 * 1024);
      debugInfo.push(sizeMB.toFixed(1) + 'MB');
      if (sizeMB < 0.05 || sizeMB > 200) continue;

      const initResp = await this.helpers.httpRequest({
        method: 'POST', url: 'https://generativelanguage.googleapis.com/upload/v1beta/files?key=' + GEMINI_KEY,
        headers: { 'X-Goog-Upload-Protocol': 'resumable', 'X-Goog-Upload-Command': 'start', 'X-Goog-Upload-Header-Content-Length': buf.length.toString(), 'X-Goog-Upload-Header-Content-Type': 'video/mp4', 'Content-Type': 'application/json' },
        body: JSON.stringify({ file: { displayName: 'src_' + Date.now() + '.mp4' } }), returnFullResponse: true
      });
      const uploadUrl = initResp.headers['x-goog-upload-url'];
      if (!uploadUrl) continue;

      const uploadResp = await this.helpers.httpRequest({
        method: 'POST', url: uploadUrl,
        headers: { 'Content-Length': buf.length.toString(), 'X-Goog-Upload-Offset': '0', 'X-Goog-Upload-Command': 'upload, finalize' },
        body: buf, returnFullResponse: true, timeout: 240000
      });
      const fileInfo = typeof uploadResp.body === 'string' ? JSON.parse(uploadResp.body) : uploadResp.body;
      let fileName = fileInfo?.file?.name;
      fileUri = fileInfo?.file?.uri || '';
      let fileState = fileInfo?.file?.state || 'PROCESSING';

      let polls = 0;
      while (fileState === 'PROCESSING' && polls < 60) {
        await new Promise(r => setTimeout(r, 5000)); polls++;
        const sr = await this.helpers.httpRequest({ method: 'GET', url: 'https://generativelanguage.googleapis.com/v1beta/' + fileName + '?key=' + GEMINI_KEY });
        const sd = typeof sr === 'string' ? JSON.parse(sr) : sr;
        fileState = sd.state; fileUri = sd.uri || fileUri;
      }
      if (fileState === 'ACTIVE' && fileUri) { usedVideo = true; debugInfo.push('VIDEO_READY'); }
      else { fileUri = ''; debugInfo.push('state=' + fileState); }
    } catch (e) { debugInfo.push('fail:' + e.message.substring(0, 60)); }
  }

  // STEP 1B: Instagram thumbnail from oEmbed
  if (!usedVideo && item.ig_thumbnail_base64) {
    thumbnailBase64List.push(item.ig_thumbnail_base64);
    usedThumbnails = true;
    debugInfo.push('IG_THUMBNAIL');
  }

  // STEP 2: Fallback - multiple YouTube thumbnails
  if (!usedVideo && !usedThumbnails && item.video_id && item.source_type === 'youtube') {
    const vid = item.video_id;
    const thumbUrls = [
      'https://img.youtube.com/vi/' + vid + '/maxresdefault.jpg',
      'https://img.youtube.com/vi/' + vid + '/sddefault.jpg',
      'https://img.youtube.com/vi/' + vid + '/hqdefault.jpg',
      'https://img.youtube.com/vi/' + vid + '/1.jpg',
      'https://img.youtube.com/vi/' + vid + '/2.jpg',
      'https://img.youtube.com/vi/' + vid + '/3.jpg'
    ];
    for (const tUrl of thumbUrls) {
      try {
        const tr = await this.helpers.httpRequest({ method: 'GET', url: tUrl, encoding: 'arraybuffer', returnFullResponse: true, timeout: 10000 });
        const b = Buffer.from(tr.body);
        if (b.length > 5000) thumbnailBase64List.push(b.toString('base64'));
      } catch (e) {}
    }
    if (thumbnailBase64List.length > 0) { usedThumbnails = true; debugInfo.push(thumbnailBase64List.length + ' thumbs'); }
  }

  // STEP 3: SINGLE Gemini call — analyze + generate 4 prompts
  const parts = [];
  if (usedVideo && fileUri) {
    parts.push({ fileData: { mimeType: 'video/mp4', fileUri: fileUri } });
  } else if (usedThumbnails) {
    for (let i = 0; i < Math.min(thumbnailBase64List.length, 5); i++) {
      parts.push({ inlineData: { mimeType: 'image/jpeg', data: thumbnailBase64List[i] } });
    }
  }

  const manualDesc = item.manual_description || '';

  const videoContext = usedVideo
    ? 'You are WATCHING the actual video above. Describe ONLY what you SEE. TRUST YOUR EYES over the title.'
    : usedThumbnails
    ? 'You are looking at ' + Math.min(thumbnailBase64List.length, 5) + ' screenshots from the video. TRUST THE IMAGES over the title.'
    : manualDesc
    ? 'The user has provided a manual description of the video content below. Use this as your primary source for analysis and prompt generation.'
    : 'No video or images loaded. Infer from transcript only.';

  parts.push({ text: `${videoContext}\n\nVideo Title (may be misleading): ${item.title || ''}\nDuration: ${item.duration_seconds || 0}s\nTranscript (secondary): ${(item.transcript || '').substring(0, 2000)}${manualDesc ? '\n\nUSER-PROVIDED DESCRIPTION OF THE VIDEO (use this as your primary source):\n' + manualDesc : ''}\n\n---\n\nDo TWO things in ONE response:\n\n**PART 1: Briefly analyze the video** — describe subject, setting, actions, lighting, colors, mood.\n\n**PART 2: Write 4 READY-TO-PASTE Seedance 2.0 prompts**\n\nEach prompt = one 15-second section. Together = 60-second video recreating the original.\n\nHOW THE USER WILL USE THESE IN SEEDANCE:\n- Section 1: Pasted into Seedance as TEXT-TO-VIDEO (generates first 15s clip)\n- Section 2: Pasted into Seedance with Section 1 full clip (15s) as REFERENCE VIDEO\n- Section 3: Pasted into Seedance with Section 2 full clip (15s) as REFERENCE VIDEO\n- Section 4: Pasted into Seedance with Section 3 full clip (15s) as REFERENCE VIDEO\n\nBecause sections 2-4 use the previous clip as reference video, Seedance already sees what came before. So:\n- Section 1 prompt: Describe the FULL scene from scratch (character, setting, action, style)\n- Sections 2-4 prompts: Start by describing what happens NEXT. The reference video already shows the character and setting, so focus on the NEW action and progression. Still include the character description and style for consistency, but lead with what CHANGES.\n\nCONNECTION RULES:\n- Section 1 must end with a moment that naturally leads into Section 2\n- Section 2 starts from that moment and ends leading into Section 3\n- Section 3 starts from that and ends leading into Section 4\n- Section 4 concludes the story\n- Example: Section 1 ends with \"...reaches toward the shelf.\" Section 2 starts with \"Pulling a jar from the shelf, the person...\"\n\nFAITHFULNESS: Match the original video\'s environment, lighting, colors, mood, actions.\nSame character across all 4. Same visual style.\n\nSAFETY:\n- No real people, celebrities, named individuals\n- No ethnicity, race, nationality\n- No brand names\n- Generic: \"a person\", \"a woman\", \"a man\"\n- Describe hair, clothing, build — keep anonymous\n\nFORMAT PER PROMPT:\n- 80-120 words\n- Plain English, what the viewer sees\n- Include: character appearance, specific actions, environment, lighting, colors, mood\n- End with: photorealistic, 4K, cinematic lighting, 24fps\n- NO negative words (no, not, without)\n- NO text/speech/audio mentions\n- NO camera jargon (dolly, pan, f-stop)\n\nReturn ONLY valid JSON:\n{\n  \"video_analysis\": \"2-3 sentence summary of what the video shows\",\n  \"character_description\": \"the consistent character used across all 4 sections\",\n  \"global_style\": \"visual style consistent across all sections\",\n  \"section_1_prompt\": \"READY TO PASTE into Seedance Text-to-Video. Full scene description 80-120 words.\",\n  \"section_2_prompt\": \"READY TO PASTE into Seedance with Section 1 clip as reference video. Describes what happens next. 80-120 words.\",\n  \"section_3_prompt\": \"READY TO PASTE into Seedance with Section 2 clip as reference video. 80-120 words.\",\n  \"section_4_prompt\": \"READY TO PASTE into Seedance with Section 3 clip as reference video. 80-120 words.\",\n  \"instructions\": \"Step-by-step guide for the user\"\n}` });

  const systemText = 'You analyze videos and write Seedance 2.0 prompts in a single response. Each prompt must be READY TO COPY-PASTE directly into Seedance — no assembly needed. Section 1 is text-to-video. Sections 2-4 are used with the previous clip as reference video, so Seedance already sees the character and setting. Focus sections 2-4 on what happens NEXT while maintaining character and style consistency. Output ONLY valid JSON.';

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' + GEMINI_KEY,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      contents: [{ role: 'user', parts: parts }],
      systemInstruction: { parts: [{ text: systemText }] },
      generationConfig: { temperature: 0.2 }
    }),
    timeout: 240000
  });

  const resp = typeof response === 'string' ? JSON.parse(response) : response;
  if (resp.error) throw new Error('Gemini: ' + JSON.stringify(resp.error));
  if (resp.candidates?.[0]?.finishReason === 'SAFETY') throw new Error('Gemini SAFETY filter blocked');

  let text = resp.candidates?.[0]?.content?.parts?.[0]?.text || '';
  if (!text) throw new Error('Empty Gemini response');
  text = text.replace(/[\x00-\x1F\x7F]/g, ' ');

  let parsed;
  try { parsed = JSON.parse(text); } catch (e) {
    const m = text.match(/\{[\s\S]*\}/);
    try { parsed = m ? JSON.parse(m[0]) : null; } catch (e2) { parsed = null; }
  }
  if (!parsed || !parsed.section_1_prompt) throw new Error('Parse failed: ' + text.substring(0, 300));

  const method = usedVideo ? 'VIDEO_UPLOADED' : usedThumbnails ? 'MULTI_THUMBNAIL' : 'TEXT_ONLY';

  allResults.push({ json: {
    source_url: item.source_url || '',
    video_title: item.title || '',
    status: 'prompts_ready',
    video_analysis: parsed.video_analysis || '',
    character_description: parsed.character_description || '',
    global_style: parsed.global_style || '',
    section_1_prompt: parsed.section_1_prompt || '',
    section_1_mode: 'TEXT-TO-VIDEO — just paste the prompt, no reference video needed',
    section_2_prompt: parsed.section_2_prompt || '',
    section_2_mode: 'Upload Section 1 full clip as reference video + paste this prompt',
    section_3_prompt: parsed.section_3_prompt || '',
    section_3_mode: 'Upload Section 2 full clip as reference video + paste this prompt',
    section_4_prompt: parsed.section_4_prompt || '',
    section_4_mode: 'Upload Section 3 full clip as reference video + paste this prompt',
    instructions: parsed.instructions || 'Section 1: Text-to-Video (just paste prompt). Sections 2-4: upload the FULL previous 15s clip as reference video + paste prompt. No cutting needed.',
    debug_method: method,
    debug_info: debugInfo.join(' | '),
    completed_at: new Date().toISOString(),
    error: ''
  } });
} catch (err) {
  allResults.push({ json: {
    source_url: item.source_url || '',
    video_title: item.title || '',
    status: 'error',
    video_analysis: '', character_description: '', global_style: '',
    section_1_prompt: '', section_1_mode: '',
    section_2_prompt: '', section_2_mode: '',
    section_3_prompt: '', section_3_mode: '',
    section_4_prompt: '', section_4_mode: '',
    instructions: '',
    debug_method: 'FAILED', debug_info: '',
    completed_at: new Date().toISOString(),
    error: err.message
  } });
}
}
return allResults;
